-- Durable change records. No secrets, addresses, message bodies or payment references.
-- Actor context exists only inside one atomic D1 batch; an uninstrumented write is unattributed.
CREATE TABLE IF NOT EXISTS change_events (
 id TEXT PRIMARY KEY NOT NULL, occurred_at INTEGER NOT NULL, recorded_at INTEGER NOT NULL,
 source TEXT NOT NULL, actor TEXT NOT NULL, actor_type TEXT NOT NULL,
 action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL,
 summary TEXT NOT NULL, status TEXT NOT NULL, changes TEXT NOT NULL CHECK(json_valid(changes)),
 evidence_url TEXT, evidence_ref TEXT
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS change_events_time ON change_events(occurred_at DESC,id DESC);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS change_events_source_time ON change_events(source,occurred_at DESC,id DESC);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS change_history_sync(source TEXT PRIMARY KEY NOT NULL,synced_at INTEGER NOT NULL,state TEXT NOT NULL,description TEXT NOT NULL);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS change_context(id INTEGER PRIMARY KEY CHECK(id=1),actor TEXT NOT NULL,actor_type TEXT NOT NULL,source TEXT NOT NULL,action TEXT,summary TEXT);
--> statement-breakpoint
CREATE TRIGGER IF NOT EXISTS change_events_no_update BEFORE UPDATE ON change_events BEGIN SELECT RAISE(ABORT,'Change history is append-only'); END;
--> statement-breakpoint
CREATE TRIGGER IF NOT EXISTS change_events_no_delete BEFORE DELETE ON change_events BEGIN SELECT RAISE(ABORT,'Change history is append-only'); END;
--> statement-breakpoint
CREATE TRIGGER IF NOT EXISTS change_events_no_replace BEFORE INSERT ON change_events WHEN EXISTS(SELECT 1 FROM change_events e WHERE e.id=NEW.id AND (e.occurred_at IS NOT NEW.occurred_at OR e.recorded_at IS NOT NEW.recorded_at OR e.source IS NOT NEW.source OR e.actor IS NOT NEW.actor OR e.actor_type IS NOT NEW.actor_type OR e.action IS NOT NEW.action OR e.entity_type IS NOT NEW.entity_type OR e.entity_id IS NOT NEW.entity_id OR e.summary IS NOT NEW.summary OR e.status IS NOT NEW.status OR e.changes IS NOT NEW.changes OR e.evidence_url IS NOT NEW.evidence_url OR e.evidence_ref IS NOT NEW.evidence_ref)) BEGIN SELECT RAISE(ABORT,'Change history is append-only'); END;
